// Package hashset provides open-addressing hash sets specialised for each
// supported element type (Int8…Int64, Char, Float32, Float64, Bool), with
// immutable and synchronized wrappers. Go has no method-level generics, so the
// per-type sources are machine-generated rather than hand-maintained.
//
// Production sources are regenerated by the in-repo code generator. Run:
//
//	go generate ./hashset/...
//
// Test files are hand-maintained.
package hashset

//go:generate go run ../internal/codegen hashset
